public class SeatCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            SeatCounter c = new SeatCounter(5);
            check("fresh remaining", 5, c.remaining());
            check("reserve(3)", true, c.reserve(3));
            check("reserved after reserve(3)", 3, c.getReserved());
            check("reserve(3) overflows", false, c.reserve(3));
            check("remaining unchanged after failed reserve", 2, c.remaining());
            check("reserve(0) rejected", false, c.reserve(0));
            check("release(9) rejected", false, c.release(9));
            check("release(3)", true, c.release(3));
            check("reserved back to zero", 0, c.getReserved());

            SeatCounter tiny = new SeatCounter(-4);
            check("negative capacity becomes 0", 0, tiny.remaining());
            check("cannot reserve on empty house", false, tiny.reserve(1));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

